values ('bbbb0003-0000-4000-8000-00000000002a', 'en', null, 'E-commerce & Online Business', 'Learn how online stores actually work, from picking a business model to taking payments, shipping orders, and winning repeat customers. This course turns the sprawling subject of selling on the internet into ten focused lessons you can finish in an afternoon. Structure adapted from the E-commerce article on Wikipedia, the free encyclopedia (CC BY-SA 4.0).', null, 'foundations', 42, true, 'business', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0003-0000-4000-8000-00000000002a', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"In e-commerce, ''B2C'' stands for which kind of selling?","options":["business to consumer","business to channel","brand to carrier","buyer to customer"],"answer":0,"explanation":"B2C is a business selling directly to individual shoppers, the most familiar online retail model - see ''What e-commerce is''."},{"prompt":"A seller who lists products on Amazon, Etsy, or eBay is selling through a...","options":["payment gateway","marketplace","shipping carrier","search engine"],"answer":1,"explanation":"A marketplace is a site that hosts many sellers and brings its own shoppers - see ''Ways to sell online''."},{"prompt":"Shopify is best described as...","options":["a national bank","a social network","a hosted platform for building your own store","a tax authority"],"answer":2,"explanation":"Shopify gives you the software to run your own branded storefront without coding it from scratch."},{"prompt":"Dropshipping means that...","options":["you keep all stock in your home","the supplier ships each order directly to the customer","you only sell to local buyers","returns are never allowed"],"answer":1,"explanation":"In dropshipping you hold no inventory; the supplier fulfills orders on your behalf."},{"prompt":"A store''s conversion rate measures...","options":["total yearly revenue","the share of visitors who complete a purchase","how fast orders ship","the number of product photos"],"answer":1,"explanation":"Conversion rate is buyers divided by visitors, the core measure of how well a store sells."},{"prompt":"Average order value (AOV) is calculated as...","options":["profit minus costs","clicks divided by ads","total revenue divided by number of orders","refunds divided by sales"],"answer":2,"explanation":"AOV tells you how much an average customer spends per order - see ''Service, metrics''."},{"prompt":"Search engine optimization (SEO) is a way to...","options":["pay for each click to your site","earn unpaid traffic from search results over time","print shipping labels","set sales tax rates"],"answer":1,"explanation":"SEO earns ''organic'' visits by making pages that search engines rank well, without paying per click."},{"prompt":"A third-party logistics (3PL) provider handles...","options":["writing your product descriptions","setting your retail prices","designing your logo","storing, packing, and shipping your orders"],"answer":3,"explanation":"A 3PL takes over warehousing and fulfillment so you do not pack boxes yourself."}]}'::jsonb, null, 10),
  (2, 'What e-commerce is and its business models', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain in plain words what e-commerce is, name the four main business models, and sort real companies into the right one. Warm-up: when you buy a phone case straight from the maker''s own website, who is selling, and who is buying? Keep that pair in mind - every model below is just a different answer to it."},{"heading":"The idea","text":"E-commerce is the buying and selling of goods and services over the internet, together with the transfer of money and data needed to complete each sale. It covers a tiny maker shipping one necklace and a giant retailer moving millions of parcels. We group the trade by who is on each side of the deal. B2C, business to consumer, is a company selling to individual shoppers, the familiar online shop. B2B, business to business, is one company selling to another, often in bulk and on invoice terms, such as a supplier selling parts to a factory. C2C, consumer to consumer, is individuals selling to each other through a shared platform, like secondhand listings. D2C, direct to consumer, is a brand that once sold only through middlemen now selling straight to the public from its own site, keeping the margin and the customer relationship. Knowing your model tells you who you must persuade, how you price, and how orders flow."},{"heading":"Key concepts & examples","text":"Picture four stores. A clothing brand running its own shop and shipping to anyone who orders is B2C and, because it skips wholesalers, also D2C. A company that sells packaging cartons to other businesses by the pallet, with 30-day invoices and volume discounts, is B2B. A site where ordinary people list used furniture and buy it from each other, with the platform taking a small fee, is C2C. The same platform can host more than one model at once: a marketplace may carry both professional sellers reaching shoppers (B2C) and private individuals clearing out a closet (C2C). D2C has grown fast because a brand that owns its website owns its data, its prices, and the full relationship, rather than renting shelf space from a retailer. When you plan a store, write down your model in one sentence, because it decides almost everything that follows, from the words on your homepage to the paperwork at tax time."},{"heading":"Your turn","text":"1) A bakery sells cakes to walk-in households through its own website - which model? 2) A firm sells industrial glue to other factories in bulk - which model? 3) A hobbyist sells a used camera to another person on a listings site - which model? 4) A razor brand that used to sell only in shops now ships straight from its site - which two labels fit? 5) Name the two sides of any e-commerce deal. Answers: 1) B2C. 2) B2B. 3) C2C. 4) B2C and D2C (direct to consumer, bypassing retailers). 5) a seller and a buyer - fixing who they are defines the model."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating ''e-commerce'' as only big online shops, when it spans single-item sellers, wholesalers, and resale between individuals. Mistake: confusing B2B with B2C because both sell products - the difference is the buyer, a business or a person, and that changes pricing, order size, and payment terms. Exit: (a) What do the letters in D2C stand for, and what does the brand cut out? (b) A marketplace of used goods between private people is which model? Answers: direct to consumer, cutting out wholesalers and retailers so the brand sells straight to the public; C2C, consumer to consumer."}]}'::jsonb, 'A business model answers one question: who sells to whom? Fix that first, because it shapes your pricing, marketing, and even your tax obligations.', 12),
  (3, 'Ways to sell online: your own store or a marketplace', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Compare the three main routes to selling online - your own store, a marketplace, and a hosted platform - and pick a sensible starting mix for a new business. Warm-up: if you opened a shop tomorrow, would you rather have instant customers but little control, or full control but no visitors on day one? That trade-off is the whole lesson."},{"heading":"The idea","text":"There are two broad places to sell, and one tool that makes the first place easy. The first place is your own store, a website at your own web address that you control end to end. You set the look, own the customer list, and keep the full margin, but no one arrives until you earn traffic. The second place is a marketplace, a large site like Amazon, Etsy, or eBay that already has millions of shoppers searching every day. You list your product there and borrow that audience, but you pay fees, compete beside rivals on the same page, and rarely learn who your customer is. The tool is a hosted platform such as Shopify, which hands you the software to run your own store without building it from code. You pick a theme, add products, connect a payment method, and you are live. In short: marketplaces trade reach for control, your own store trades control for the work of finding shoppers, and a platform lowers the cost of running that store."},{"heading":"Key concepts & examples","text":"A new candle maker might list on Etsy first, because buyers are already there searching for candles, and make early sales within days. The cost is a listing fee plus a cut of each sale, and Etsy, not the maker, owns the relationship with those buyers. As the brand grows, the maker opens a Shopify store at its own address, where it controls the design, collects email addresses, and keeps more margin per sale. Many sellers run both at once: the marketplace is a discovery channel that pulls in first-time buyers, and the owned store is where loyal customers return and where the brand can tell its story. eBay and similar sites also support auctions and resale, which suit used or rare goods. The right choice depends on your goal: fast proof that people will buy points to a marketplace, while building a lasting brand with repeat buyers points to your own store, usually on a platform."},{"heading":"Your turn","text":"1) Which route gives you built-in shoppers from day one? 2) Which route lets you keep the customer email list? 3) What is Shopify an example of? 4) Name one cost of selling on a marketplace. 5) Why do many sellers use both a marketplace and their own store? Answers: 1) a marketplace such as Amazon, Etsy, or eBay. 2) your own store. 3) a hosted platform for running your own store. 4) listing and sales fees, plus competing beside rivals and not owning the customer. 5) the marketplace brings discovery and first sales, while the owned store builds repeat buyers and brand."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming your own store will have visitors the moment it launches - a new site starts with zero traffic and you must earn every visit. Mistake: treating a marketplace as ''free reach'' and ignoring the fees and the lost customer relationship. Exit: (a) In one phrase, what does a marketplace trade away in return for its built-in audience? (b) What does a hosted platform like Shopify save you from doing? Answers: control and the direct customer relationship (plus fees per sale); building and maintaining store software from scratch."}]}'::jsonb, 'Marketplaces bring traffic but rent your customer relationship; your own store makes you earn the traffic but lets you keep the data. Most sellers end up using both.', 13),
  (4, 'Building the online store: listings, pricing, and checkout', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Write a product listing that sells, set a price that holds up, and spot the leaks in a checkout flow that cost you orders. Warm-up: think of the last time you abandoned an online cart. What made you stop? Hold that memory - most of this lesson is about removing exactly those reasons."},{"heading":"The idea","text":"An online store is built from three parts that each do a job. The product listing is the page for a single item: its title, photos, description, options, and price. Clear photos from several angles and a description that answers real buyer questions do most of the selling, because shoppers cannot touch the product. Pricing is the number you charge. It must cover your product cost, your fees, and your shipping, and still leave a margin, while staying believable next to competitors. Many sellers start from cost and add a markup, then sanity-check against the market. The checkout is the path from ''add to cart'' to ''order placed.'' It should be short, ask only for what is needed, show the full price including shipping early, and offer trusted payment options. Each page has one job: the listing earns the click to buy, the price survives a quick comparison, and the checkout gets out of the way."},{"heading":"Key concepts & examples","text":"Suppose a mug costs you 4 to make and ship, and marketplace or platform fees take about 1 per sale. If you price it at 15, your margin is 10 before marketing, and you can check that 15 sits sensibly among similar mugs. A strong listing for that mug leads with a bright main photo, adds shots of the handle and the base, lists the size and dishwasher-safety as options or facts, and writes two short paragraphs answering ''will it keep coffee hot'' and ''is it microwave safe.'' At checkout, the biggest leak is surprise cost: a shopper who sees a low price but meets a large shipping fee at the final step often quits. Showing shipping up front, allowing guest checkout rather than forcing an account, and trimming the form to name, address, and payment all lift completed orders. Test your own checkout on a phone, because that is where most shoppers now are."},{"heading":"Your turn","text":"1) Name the three parts a store is built from. 2) If a product costs 6 to make and ship and fees take 2, what margin does a price of 20 leave before marketing? 3) Give one reason a buyer abandons a cart at the final step. 4) Why offer guest checkout? 5) Where should you test a checkout first? Answers: 1) the listing, the price, and the checkout. 2) 20 minus 6 minus 2 = 12. 3) a surprise shipping fee shown only at the end (any hidden cost). 4) forcing account creation adds friction and loses buyers; guests convert better. 5) on a phone, where most shoppers are."},{"heading":"Common mistakes & exit ticket","text":"Mistake: hiding shipping cost until the last screen, which trains buyers to abandon. Mistake: pricing from a guess instead of from your real costs plus fees, so you sell at a loss without knowing it. Mistake: a listing with one blurry photo and no answers to obvious questions. Exit: (a) What is the single best thing to show early in checkout to reduce abandonment? (b) What three numbers must a price cover before margin? Answers: the full price including shipping (no surprises later); product cost, fees, and shipping."}]}'::jsonb, 'Every extra field or step in checkout is a place a buyer can quit. Shorter is almost always better.', 13),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"A brand that once sold only through shops and now ships straight from its own website is practicing...","options":["B2B","C2C","D2C","wholesale only"],"answer":2,"explanation":"D2C, direct to consumer, cuts out the middlemen so the brand owns the customer."},{"prompt":"The main trade-off of selling on a marketplace is that you gain built-in shoppers but...","options":["pay no fees at all","give up control and the customer relationship","cannot sell physical goods","must build your own software"],"answer":1,"explanation":"Marketplaces trade reach for control: fees apply and you rarely own the customer."},{"prompt":"Shopify''s main role for a seller is to...","options":["act as a bank","provide the software to run your own store","replace all marketing","set your sales tax"],"answer":1,"explanation":"A hosted platform gives you a storefront without coding it yourself."},{"prompt":"The most common reason a shopper abandons a cart at the final step is...","options":["too many product photos","a surprise shipping or extra cost","a price that is too low","a guest checkout option"],"answer":1,"explanation":"Unexpected costs at the end are the classic checkout leak; show the full price early."},{"prompt":"If a product costs 5 to make and ship and fees take 2, a price of 18 leaves a pre-marketing margin of...","options":["11","13","18","7"],"answer":0,"explanation":"18 minus 5 minus 2 = 11."},{"prompt":"A site where private individuals buy and sell used goods from each other is an example of...","options":["B2B","C2C","D2C","3PL"],"answer":1,"explanation":"Consumer to consumer trade runs between individuals on a shared platform."}]}'::jsonb, null, 8),
  (6, 'Payments, taxes, shipping, and fulfillment', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe how an online payment moves, why sales tax depends on where the buyer is, and choose a fulfillment method - doing it yourself, dropshipping, or using a 3PL. Warm-up: between the moment a buyer clicks ''pay'' and the parcel arriving, list every step you can think of. By the end you will be able to name who can handle each one."},{"heading":"The idea","text":"Four jobs turn an order into a delivered parcel. Payments: a payment processor such as Stripe or PayPal takes the buyer''s card details securely, checks the funds with the bank, and moves the money to you, keeping a small fee. You almost never touch raw card numbers yourself, which keeps you safer and simpler. Taxes: many places charge sales tax or value-added tax based on where the buyer is, so your store must calculate and collect the right amount and later pass it to the authorities. Shipping: you decide who carries the parcel, how fast, and who pays - free shipping is really a cost you have folded into the price. Fulfillment: the physical work of storing, packing, and sending goods. You can do it from your own space, let a supplier ship for you through dropshipping, or hand warehousing and packing to a third-party logistics provider, a 3PL, that ships in your name as you grow."},{"heading":"Key concepts & examples","text":"A buyer pays 25 for a shirt. Stripe might take roughly 1 in fees and pass you the rest a few days later. If the buyer is in a region with a 10 percent sales tax, your store adds about 2.50 at checkout, which you hold and later remit to the tax office - it was never your money. For getting the shirt out the door, a brand-new seller often packs orders at the kitchen table and drops them at the carrier. A seller using dropshipping never sees the shirt: the order flows to a supplier who ships it straight to the buyer, so there is no stock to buy up front, though margins are thinner and quality is harder to control. A growing brand sends its stock to a 3PL warehouse, which stores the shirts, picks and packs each order, and ships it under the brand''s label, freeing the founder from the packing bench."},{"heading":"Your turn","text":"1) Name one payment processor and say what it does. 2) Why do you collect sales tax but not keep it? 3) In dropshipping, who ships the product to the buyer? 4) What does a 3PL do for a growing store? 5) ''Free shipping'' really means what? Answers: 1) Stripe or PayPal - it securely takes the buyer''s card, verifies funds, and transfers the money to you for a fee. 2) it is owed to the tax authority; you only collect and remit it. 3) the supplier, directly, so you hold no stock. 4) it stores your goods and picks, packs, and ships each order in your name. 5) the shipping cost has been folded into the product price."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating collected sales tax as revenue and spending it, then owing it later. Mistake: assuming dropshipping is risk-free - you trade stock risk for thin margins and less control over quality and delivery time. Mistake: offering ''free'' shipping without raising the price to cover it. Exit: (a) Who handles card details so you do not have to? (b) Name the three fulfillment choices covered here. Answers: a payment processor such as Stripe or PayPal; doing it yourself, dropshipping, and using a 3PL (third-party logistics provider)."}]}'::jsonb, 'Fulfillment is everything that happens after ''buy'': taking the money, charging the right tax, and getting the box to the door. Each step can be done yourself or handed off.', 14),
  (7, 'Driving traffic and lifting conversion', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"List the main ways to bring visitors to a store, tell paid traffic from earned traffic, and explain conversion rate optimization as turning more of those visitors into buyers. Warm-up: your store had 2000 visitors last month and 40 sales. What is your conversion rate, and would you rather double the visitors or double that rate? Hold your answer."},{"heading":"The idea","text":"Selling online is two problems: getting people to the store, and getting them to buy once there. Traffic has two flavors. Earned traffic builds over time without paying per visit: search engine optimization (SEO) makes pages that rank in search results, content such as guides and blog posts pulls in people researching a problem, email reaches customers who already know you, and social posts spread by sharing. Paid traffic buys visits now: paid ads on search engines or social platforms charge you per click or per view, giving fast reach that stops when you stop paying. Once visitors arrive, conversion rate optimization, or CRO, is the work of lifting the share who buy. Conversion rate is buyers divided by visitors. Small fixes - clearer photos, trust signals, a shorter checkout, faster pages - can raise it, and because traffic and conversion multiply into sales, a higher rate makes every visit, paid or earned, worth more."},{"heading":"Key concepts & examples","text":"A store with 2000 visitors and 40 sales has a conversion rate of 40 divided by 2000, or 2 percent. Suppose each paid visitor costs 0.50. Buying 2000 more visits costs 1000 and, at 2 percent, yields 40 more sales. Now suppose instead that CRO work - adding reviews, cutting a checkout step, and showing a clear return policy - lifts the rate to 3 percent. The original 2000 visitors now produce 60 sales, 20 more, for the cost of some fixes and no extra ad spend, and every future visit is worth more too. That is why experienced sellers do both: email and SEO build a base of cheap, compounding earned traffic, paid ads top it up when needed, and steady CRO means none of that traffic is wasted. Measure one change at a time so you know what moved the rate."},{"heading":"Your turn","text":"1) A store has 5000 visitors and 150 sales - what is the conversion rate? 2) Name two sources of earned traffic. 3) What stops the moment you stop paying? 4) Define conversion rate in words. 5) Give one change that commonly lifts conversion. Answers: 1) 150 divided by 5000 = 3 percent. 2) any two of SEO, content, email, and social. 3) paid ads (paid traffic). 4) the share of visitors who complete a purchase, buyers divided by visitors. 5) adding reviews, shortening checkout, faster pages, or a clear return policy (any one)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: pouring money into ads while the store converts poorly, so you pay for visitors who leak straight out. Mistake: confusing traffic with sales - more visitors do nothing if none of them buy. Mistake: changing five things at once during CRO, so you cannot tell what worked. Exit: (a) Name the two problems selling online must solve. (b) If visitors stay flat but conversion rate doubles, what happens to sales? Answers: getting people to the store and getting them to buy; sales double, since sales equal visitors times conversion rate."}]}'::jsonb, 'Traffic and conversion multiply: 1000 visitors at a 2 percent conversion rate is the same 20 sales as 500 visitors at 4 percent. Work on whichever is weaker.', 14),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"e-commerce","translation":"buying and selling goods or services over the internet, with the money and data to complete each sale","example":"Her candle shop moved online, so the whole business is now e-commerce."},{"term":"marketplace","translation":"a large site that hosts many sellers and brings its own shoppers, such as Amazon, Etsy, or eBay","example":"He listed his prints on a marketplace to reach buyers he could not find alone."},{"term":"D2C (direct to consumer)","translation":"a brand selling straight to the public from its own site, skipping wholesalers and retailers","example":"By going D2C, the mattress brand kept the full margin and the customer data."},{"term":"dropshipping","translation":"a model where the supplier ships each order directly to the customer, so the seller holds no stock","example":"With dropshipping she launched with no inventory, but her margins were thin."},{"term":"3PL (third-party logistics)","translation":"an outside company that stores, picks, packs, and ships a store''s orders on its behalf","example":"Once orders passed a hundred a day, they handed fulfillment to a 3PL."},{"term":"conversion rate","translation":"the share of visitors who complete a purchase, found by dividing buyers by visitors","example":"Shortening the checkout lifted the conversion rate from 2 to 3 percent."},{"term":"average order value (AOV)","translation":"total revenue divided by the number of orders, the typical amount spent per order","example":"Bundling two items raised the average order value from 25 to 34."},{"term":"customer lifetime value (LTV)","translation":"the total profit a business expects from one customer across the whole relationship","example":"Because buyers reordered coffee monthly, the lifetime value far exceeded the first sale."}]}'::jsonb, null, 9),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"A payment processor such as Stripe or PayPal mainly...","options":["sets your product prices","securely takes the card and moves the money to you for a fee","ships your parcels","writes your listings"],"answer":1,"explanation":"Processors handle card details and fund transfer so you never touch raw card numbers."},{"prompt":"Sales tax that your store collects at checkout is...","options":["extra profit to keep","owed to the tax authority and remitted later","a shipping charge","a processor fee"],"answer":1,"explanation":"You only collect and pass it on; it was never your money."},{"prompt":"In dropshipping, the seller...","options":["warehouses all stock at home","holds no stock and the supplier ships to the buyer","refuses returns","only sells services"],"answer":1,"explanation":"The supplier fulfills orders directly, so there is no inventory to buy up front."},{"prompt":"Which is a source of EARNED (not paid) traffic?","options":["pay-per-click search ads","paid social ads","search engine optimization (SEO)","paid influencer shoutouts"],"answer":2,"explanation":"SEO earns unpaid visits over time; the others charge per click or placement."},{"prompt":"A store with 4000 visitors and 120 sales has a conversion rate of...","options":["3 percent","12 percent","30 percent","0.3 percent"],"answer":0,"explanation":"120 divided by 4000 equals 0.03, or 3 percent."},{"prompt":"If visitors stay the same but conversion rate doubles, sales will...","options":["stay flat","halve","double","fall to zero"],"answer":2,"explanation":"Sales equal visitors times conversion rate, so doubling the rate doubles sales."}]}'::jsonb, null, 8),
  (10, 'Service, metrics, and where e-commerce is heading', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Handle customer service, reviews, and returns as growth tools, read the four metrics that run a store, and name the trends reshaping online selling. Warm-up: think of a store you buy from again and again. What keeps you coming back - the price, or the way they treat you? Hold that answer; it points at everything below."},{"heading":"The idea","text":"A sale is the start of a relationship, not the end. Customer service - fast, honest replies when something goes wrong - turns an upset buyer into a repeat one. Reviews are social proof: shoppers trust other shoppers, so inviting honest reviews and answering the critical ones builds confidence and lifts conversion. Returns feel like a loss, but a clear, easy return policy actually increases sales, because it removes the risk of buying unseen; a smooth return often earns a second purchase. To steer all this you watch four numbers. Conversion rate is the share of visitors who buy. Average order value, AOV, is revenue divided by orders. Customer acquisition cost, CAC, is what you spend on marketing to win one new customer. Customer lifetime value, LTV, is the total profit one customer brings over time. A healthy store keeps LTV well above CAC, so each customer earns back what they cost to win, and then some."},{"heading":"Key concepts & examples","text":"Say ads cost 2000 last month and brought 100 new customers, so CAC is 20. If the average new customer spends 25 on the first order with a 10 margin, the first sale alone does not cover the 20 to win them. But if those customers reorder and their lifetime value is 80 in profit, then LTV of 80 against CAC of 20 is a strong four-to-one ratio, and the business grows. This is why service and reviews matter in money terms: they raise repeat purchases, which raises LTV. Trends are pushing the same way. Mobile commerce means most shoppers now browse and buy on phones, so a store that is slow or clumsy on a small screen loses sales before service even begins. Subscriptions turn one-off buyers into recurring revenue - coffee, razors, or software billed monthly - which smooths income and lifts LTV, because a subscriber keeps paying until they choose to stop."},{"heading":"Your turn","text":"1) Why does an easy return policy often raise sales? 2) Write the formula for conversion rate. 3) If marketing costs 3000 and wins 150 customers, what is CAC? 4) Which should be larger for a healthy store, LTV or CAC? 5) Name two trends shaping e-commerce. Answers: 1) it removes the risk of buying unseen, so more people buy, and a smooth return earns repeat purchases. 2) buyers divided by visitors. 3) 3000 divided by 150 = 20. 4) LTV, which should sit comfortably above CAC. 5) mobile commerce and subscriptions."},{"heading":"Common mistakes & exit ticket","text":"Mistake: chasing new customers through ads while ignoring service and reviews, so CAC stays high and LTV stays low. Mistake: hiding or complicating returns, which scares off cautious buyers and costs more sales than the returns save. Mistake: building a store that works on a desktop but frustrates the phone users who are now the majority. Exit: (a) Which two metrics do you compare to see if winning a customer pays off? (b) Name one way subscriptions help a store. Answers: customer lifetime value (LTV) against customer acquisition cost (CAC); they create recurring revenue and raise lifetime value by keeping buyers paying over time."}]}'::jsonb, 'Winning the first sale is marketing; winning the second is service and product. The cheapest customer to sell to is the one you already have.', 13)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0003-0000-4000-8000-00000000002a' and l.position = v.pos
);
